//! Fixture-based integration tests: each reader must resolve the car
//! name from a recorded shared-memory image (generated by
//! `fixtures/generate_fixtures.py`; see `docs/TELEMETRY-RUST.md` §4).
//!
//! These run on Linux — the readers' pure `read_from_*` entry points
//! parse the fixture bytes exactly as the Windows `read()` would parse
//! a live mapped view. Live-game end-to-end (real session on the owner
//! PC) is still open; see the doc's Windows-only gaps.

use rsh_telemetry::{AcReader, AccReader, IRacingReader, SessionState, SliceMap, TelemetryReader};
use std::path::PathBuf;

fn fixture(name: &str) -> Vec<u8> {
    let path: PathBuf = [env!("CARGO_MANIFEST_DIR"), "tests", "fixtures", name]
        .iter()
        .collect();
    std::fs::read(&path)
        .unwrap_or_else(|err| panic!("fixture {} unreadable: {err}", path.display()))
}

#[test]
fn ac_reader_resolves_car_name_from_fixture() {
    let static_bytes = fixture("ac_static.bin");
    let graphics_bytes = fixture("ac_graphics.bin");
    let snapshot = AcReader::read_from_maps(
        &SliceMap::new(&static_bytes),
        &SliceMap::new(&graphics_bytes),
    )
    .expect("AC fixture must parse");
    assert_eq!(snapshot.car_model, "ferrari_488_gt3");
    assert_eq!(snapshot.car_display, "ferrari_488_gt3");
    assert_eq!(snapshot.track_name, "monza");
    assert_eq!(snapshot.state, SessionState::OnTrack);
    assert!(snapshot.is_on_track());
}

#[test]
fn acc_reader_resolves_car_name_from_fixture() {
    let static_bytes = fixture("acc_static.bin");
    let graphics_bytes = fixture("acc_graphics.bin");
    let snapshot = AccReader::read_from_maps(
        &SliceMap::new(&static_bytes),
        &SliceMap::new(&graphics_bytes),
    )
    .expect("ACC fixture must parse");
    // ACC reports a display name; the normalised key must match AC's.
    assert_eq!(snapshot.car_model, "ferrari_488_gt3_evo");
    assert_eq!(snapshot.car_display, "Ferrari 488 GT3 Evo");
    assert_eq!(snapshot.track_name, "spa");
    assert_eq!(snapshot.state, SessionState::OnTrack);
}

#[test]
fn ac_reader_menu_fixture_is_not_on_track() {
    let static_bytes = fixture("ac_static.bin");
    let graphics_bytes = fixture("ac_graphics_menu.bin");
    let snapshot = AcReader::read_from_maps(
        &SliceMap::new(&static_bytes),
        &SliceMap::new(&graphics_bytes),
    )
    .expect("menu fixture must still parse");
    assert_eq!(snapshot.car_model, "ferrari_488_gt3");
    assert_eq!(snapshot.state, SessionState::Menu);
    assert!(!snapshot.is_on_track());
}

#[test]
fn ac_reader_rejects_short_static_fixture() {
    let static_bytes = fixture("ac_static_short.bin");
    let graphics_bytes = fixture("ac_graphics.bin");
    assert!(
        AcReader::read_from_maps(
            &SliceMap::new(&static_bytes),
            &SliceMap::new(&graphics_bytes)
        )
        .is_none()
    );
}

#[test]
fn iracing_reader_resolves_car_name_from_fixture() {
    let image = fixture("iracing_shm.bin");
    let snapshot =
        IRacingReader::read_from_map(&SliceMap::new(&image)).expect("iRacing fixture must parse");
    // Player is DriverCarIdx 0; the second driver must not be picked.
    assert_eq!(snapshot.car_display, "Ferrari 488 GT3 Evo 2020");
    assert_eq!(snapshot.car_model, "ferrari_488_gt3_evo_2020");
    assert_eq!(snapshot.track_name, "Spa-Francorchamps");
    assert_eq!(snapshot.state, SessionState::OnTrack);
}

#[test]
fn iracing_reader_rejects_corrupt_fixture() {
    let mut image = fixture("iracing_shm.bin");
    // Zero the header: ver 0 + not connected.
    image[..8].fill(0);
    assert!(IRacingReader::read_from_map(&SliceMap::new(&image)).is_none());
    assert!(IRacingReader::read_from_map(&SliceMap::new(&[])).is_none());
}

#[test]
fn readers_share_one_contract() {
    // Every reader exposes the same trait surface the watcher will use.
    let readers: [Box<dyn TelemetryReader + Send>; 3] = rsh_telemetry::all_readers();
    assert_eq!(readers.len(), 3);
    for reader in &readers {
        // No game runs in this sandbox: live reads must be `None`,
        // never a panic or an error.
        assert_eq!(reader.read_car(), None);
    }
}
